const settings = $('Set Bulk Research Settings').first().json;
const maxBusinesses = Number(settings.maxBusinesses);
const defaultMaxContacts = Number(settings.defaultMaxContactsPerBusiness);

if (!Number.isInteger(maxBusinesses) || maxBusinesses < 1 || maxBusinesses > 25) {
  throw new Error('maxBusinesses must be an integer from 1 through 25.');
}
if (!Number.isInteger(defaultMaxContacts) || defaultMaxContacts < 1 || defaultMaxContacts > 8) {
  throw new Error('defaultMaxContactsPerBusiness must be an integer from 1 through 8.');
}
if (!String(settings.defaultDecisionMakerTitles || '').trim()) {
  throw new Error('Enter at least one default decision-maker title.');
}

const companies = [];
const seen = new Set();
const disabledValues = new Set(['false', 'no', '0', 'disabled', 'skip']);

for (const item of $input.all()) {
  const row = item.json || {};
  if (disabledValues.has(String(row.enabled ?? '').trim().toLowerCase())) continue;

  const name = String(row.company_name || '').trim();
  const websiteValue = String(row.website || '').trim();
  if (!name && !websiteValue) continue;
  if (!name || !websiteValue) {
    throw new Error('Every enabled row needs company_name and website. Check row ' + String(row.row_number || row.rowNumber || 'unknown') + '.');
  }

  const domain = websiteValue
    .toLowerCase()
    .replace(/^https?:\/\//i, '')
    .replace(/^\/\//, '')
    .split(/[\/?#]/)[0]
    .split(':')[0]
    .replace(/^www\./, '')
    .replace(/\.$/, '');

  if (!domain.includes('.') || domain === 'example.com') {
    throw new Error('Enter a real business website for ' + name + '.');
  }
  if (seen.has(domain)) continue;

  const maxContacts = Number(row.max_contacts || defaultMaxContacts);
  if (!Number.isInteger(maxContacts) || maxContacts < 1 || maxContacts > 8) {
    throw new Error('max_contacts must be an integer from 1 through 8 for ' + name + '.');
  }

  const title = String(row.decision_maker_titles || settings.defaultDecisionMakerTitles || '').trim();
  if (!title) throw new Error('No decision-maker title is configured for ' + name + '.');

  seen.add(domain);
  companies.push({
    companyName: name,
    domain,
    website: 'https://' + domain,
    city: String(row.city || settings.defaultCity || '').trim(),
    state: String(row.state || settings.defaultState || '').trim(),
    country: String(row.country || settings.defaultCountry || '').trim(),
    title,
    maxContacts,
  });
  if (companies.length >= maxBusinesses) break;
}

if (!companies.length) {
  throw new Error('The Businesses sheet contains no enabled rows with company_name and website.');
}

return [{ json: {
  companies,
  requestedCompanyCount: companies.length,
  firstWaitSeconds: Number(settings.firstWaitSeconds),
  secondWaitSeconds: Number(settings.secondWaitSeconds),
  researchStartedAt: new Date().toISOString(),
} }];

const raw = $json;
const context = $('If Completed Task Was Found').item.json;
const emails = new Set();
const phones = new Set();
const linkedin = new Set();
const people = [];
const seenPeople = new Set();

function visit(value) {
  if (value === null || value === undefined) return;
  if (Array.isArray(value)) { for (const item of value) visit(item); return; }
  if (typeof value !== 'object') {
    if (typeof value === 'string') {
      const text = value.trim();
      if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text)) emails.add(text.toLowerCase());
      if (/linkedin\.com\/in\//i.test(text)) linkedin.add(text);
      if (/^\+?[\d().\-\s]{7,}$/.test(text) && text.replace(/\D/g, '').length >= 7) phones.add(text);
    }
    return;
  }
  const obj = value;
  const first = obj.first_name || obj.firstName || '';
  const last = obj.last_name || obj.lastName || '';
  const name = String(obj.full_name || obj.fullName || obj.name || (first + ' ' + last)).trim();
  const title = String(obj.title || obj.job_title || obj.jobTitle || '').trim();
  if (name && (title || obj.email || obj.linkedin_url || obj.linkedinUrl)) {
    const key = (name + '|' + title).toLowerCase();
    if (!seenPeople.has(key)) { seenPeople.add(key); people.push({ name, title }); }
  }
  for (const child of Object.values(obj)) visit(child);
}
visit(raw.data ?? raw.result ?? raw);

return { json: {
  companyName: context.companyName,
  domain: context.domain,
  jobType: context.jobType,
  jobStatus: String(raw.status || 'COMPLETED'),
  taskId: String(raw.task_id || context.taskId || ''),
  emails: [...emails], phones: [...phones], linkedinUrls: [...linkedin], people,
} };

const rows = $input.all().map(item => item.json);
const companies = $('Normalize Business Rows').first().json.companies || [];
const byDomain = new Map(companies.map(company => [company.domain, {
  company_name: company.companyName,
  domain: company.domain,
  website: company.website,
  decision_maker_names: [],
  decision_maker_titles: [],
  decision_maker_emails: [],
  shared_company_emails: [],
  phone_numbers: [],
  linkedin_urls: [],
  decision_maker_job_status: 'missing',
  company_email_job_status: 'missing',
}]));

for (const row of rows) {
  const target = byDomain.get(row.domain);
  if (!target) continue;
  const emails = Array.isArray(row.emails) ? row.emails : [];
  const phones = Array.isArray(row.phones) ? row.phones : [];
  const links = Array.isArray(row.linkedinUrls) ? row.linkedinUrls : [];
  if (row.jobType === 'decision_maker') {
    target.decision_maker_job_status = row.jobStatus || 'unknown';
    target.decision_maker_emails.push(...emails);
    for (const person of Array.isArray(row.people) ? row.people : []) {
      if (person.name) target.decision_maker_names.push(person.name);
      if (person.title) target.decision_maker_titles.push(person.title);
    }
  } else if (row.jobType === 'company_email') {
    target.company_email_job_status = row.jobStatus || 'unknown';
    target.shared_company_emails.push(...emails);
  }
  target.phone_numbers.push(...phones);
  target.linkedin_urls.push(...links);
}

const unique = values => [...new Set(values.filter(Boolean))];
const output = [];
for (const row of byDomain.values()) {
  row.decision_maker_names = unique(row.decision_maker_names).join('; ');
  row.decision_maker_titles = unique(row.decision_maker_titles).join('; ');
  row.decision_maker_emails = unique(row.decision_maker_emails).join('; ');
  row.shared_company_emails = unique(row.shared_company_emails).join('; ');
  row.phone_numbers = unique(row.phone_numbers).join('; ');
  row.linkedin_urls = unique(row.linkedin_urls).join('; ');
  if (row.decision_maker_emails) {
    row.priority = 'A - decision-maker email found';
    row.recommended_next_step = 'Review the person and company context, then prepare personalized outreach for your offer.';
  } else if (row.shared_company_emails) {
    row.priority = 'B - shared company email found';
    row.recommended_next_step = 'Contact the shared company inbox and ask for the appropriate decision-maker.';
  } else if (row.phone_numbers) {
    row.priority = 'C - phone only';
    row.recommended_next_step = 'Call to identify the person responsible for the problem your offer solves.';
  } else {
    row.priority = 'D - no usable contact found';
    row.recommended_next_step = 'Pause outreach and review the website manually before spending additional enrichment credits.';
  }
  row.researched_at = new Date().toISOString();
  output.push({ json: row });
}
return output.sort((a, b) => a.json.priority.localeCompare(b.json.priority));
